export const clone=value=>structuredClone(value);
export const uid=()=>crypto.randomUUID();
export const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function safeURL(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}}
export function safeImage(value){return /^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=\s]+$/.test(value||'')?value:''}
export function step(title='New step',type='step'){return {id:uid(),title,description:'',type,screenshot:null,alt:'',branches:[]}}
export function guide(title='Untitled guide',workspaceId=null){return {id:uid(),workspaceId,title,category:'Operations',folder:'',tags:[],variables:{},steps:[step('Start here')],revision:0,dirty:true,updatedAt:new Date().toISOString(),captureBatches:[]}}
export function normalize(doc,workspaceId){if(!doc||typeof doc.title!=='string'||!Array.isArray(doc.steps)||doc.steps.length>1000)throw Error('Invalid guide file');const out=clone(doc);out.id=/^[0-9a-f-]{36}$/i.test(doc.id)?doc.id:uid();out.workspaceId=workspaceId;out.tags=Array.isArray(out.tags)?out.tags:[];out.variables=out.variables||{};out.steps=out.steps.map(s=>({...s,id:String(s.id||uid()),title:String(s.title||'Step'),description:String(s.description||''),branches:Array.isArray(s.branches)?s.branches:[]}));if(new Set(out.steps.map(s=>s.id)).size!==out.steps.length)throw Error('Duplicate step IDs');return out}
export function interpolate(text,variables){return String(text||'').replace(/\{\{([\w-]+)\}\}/g,(whole,k)=>variables[k]??whole)}
export function duplicateSteps(steps,ids){return steps.flatMap(s=>ids.has(s.id)?[s,{...clone(s),id:uid(),title:s.title+' (copy)'}]:[s])}
export function mergeSteps(steps,ids){const chosen=steps.filter(s=>ids.has(s.id));if(chosen.length<2)throw Error('Select at least two steps');const merged={...clone(chosen[0]),description:chosen.map(s=>`${s.title}\n${s.description}`).join('\n\n'),branches:[]};return steps.flatMap(s=>s.id===chosen[0].id?[merged]:ids.has(s.id)?[]:[s])}
export function stale(doc,days=90){return Date.now()-new Date(doc.reviewedAt||doc.updatedAt||0).getTime()>days*86400000}
export function history(initial){let past=[],future=[],current=clone(initial);return {record(next){past.push(current);past=past.slice(-40);current=clone(next);future=[];},undo(){if(!past.length)return null;future.push(current);current=past.pop();return clone(current)},redo(){if(!future.length)return null;past.push(current);current=future.pop();return clone(current)}}}
export const templates={SOP:['Purpose and scope','Before you begin','Complete the process','Verify the result'],Onboarding:['Welcome','Set up your account','Complete your first task','Get support'],Troubleshooting:['Identify the symptom','Check common causes','Apply the fix','Verify resolution'],Support:['Understand the request','Find the account','Resolve the issue','Confirm with the customer']};
